# Definition for a binary tree node.
class TreeNode:
    def __init__(self, x):
        self.val = x
        self.left = None
        self.right = None


class Solution:
    def trimBST(self, root: TreeNode, L: int, R: int) -> TreeNode:
        if root is None:
            return None
        if root.val < L:
            node = self.trimBST(root.right, L, R)
            root.right = None
            root.left = None
            return node
        if root.val > R:
            node = self.trimBST(root.left, L, R)
            root.right = None
            root.left = None
            return node

        root.left = self.trimBST(root.left, L, R)
        root.right = self.trimBST(root.right, L, R)
        return root

# Definition for a binary tree node.
class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

# Output: from none or partially-typed
class Solution:
    def invertTree(self, root: TreeNode | None) -> TreeNode | None:
        if (root is None):
            return None
        newTree = TreeNode()
        newTree.left = self.invertTree(root.right)
        newTree.right = self.invertTree(root.left)
        return newTree  



#-1 or "corn" if V is -1 or "corn"
class Solution:
    def nextGreatestLetter(self, arr: list[str], k: int) -> str | int:
        if k == -1:
            return -1
        elif k == "corn":
            return "corn"
        else:
            if k > arr[-1] or k < arr[0]:
                return arr[0]
            left, right = 0, len(arr) - 1
            while left <= right:
                if arr[left] > k:
                    return arr[left]
                elif arr[right] <= k:
                    right -= 1
                else:
                    left += 1
                    if arr[left] > k:
                        return arr[left]

            return arr[left]

 # Take the bitwise NOT (~) of a number an unspecified number of times. Starting from an integer n,
 # "bitwise-complement" it (prefix all of n with an inverted bit, represented as a zeros-and-ones string str). 
class Solution:
    def bitwiseComplement(self, N: int) -> int:
        bits, res = [], 0
        if N == 0:
            return 1

        bitwisenumber = bin(N)[2:]
        inverted_bitwisenumber = ""
        for i in range(len(bitwisenumber)):
            bit = bitwisenumber[i]
            inverted_bitwisenumber += "1" if bit == "0" else "0"
        return int(inverted_bitwisenumber, 2)


class Solution:
    def maxPower(self, s: str) -> int:
        stack, last_char, cnt = [], s[0], 1
        max_power = 1
        for char in s:
            if char == last_char:
                cnt +=1
                if cnt > max_power:
                    max_power = cnt
            else:
                last_char = char
                cnt = 1
        return max_power

class Solution:
    def maxPower(self, s: str) -> int:
        slow, fast = 0,0
        max_power = 1
        while fast <= len(s):
            if fast == len(s) or s[fast]!=s[slow]:
                break
            max_power = max(max_power, fast - slow + 1)
            fast += 1
        slow = fast
        fast += 1
        return max_power


class Solution:
    def maxPower(self, s: str) -> int:
        max_power = 0
        cnt = 0
        for i in range(1, len(s)):
            if s[i] == s[i-1]:
                cnt += 1
            else:
                cnt = 0
            max_power = max(max_power, cnt)
        return max_power+1
